56: /** Measure without mutating input. Ancestor containment is not a collision. */
57: export function resolveScene(scene: LineGridScene): ResolvedGridBox {
58:   const ids = new Set<string>();
59:   function visit(box: GridBox, parent: GridPoint): ResolvedGridBox {
60:     if (ids.has(box.id)) throw new Error(`Duplicate GridBox id: ${box.id}`);
61:     ids.add(box.id);
62:     integer(box.position.column, "column");
63:     integer(box.position.row, "row");
64:     if (box.minimumSize) {
65:       integer(box.minimumSize.columns, "columns");
66:       integer(box.minimumSize.rows, "rows");
67:     }
68:     const origin = { column: parent.column + box.position.column, row: parent.row + box.position.row };
69:     integer(origin.column, "absolute column");
70:     integer(origin.row, "absolute row");
71:     if (box.kind === "container") integer(box.layout.gap, "gap");
72:     const contentId = box.collapsed ? box.collapsedContentId : box.kind === "diagram" ? box.contentId : undefined;
73:     if (box.collapsed && !contentId) throw new Error(`Collapsed box ${box.id} needs collapsed content`);
74:     let size: GridSize = { columns: 1, rows: 1 };
75:     if (contentId) {
76:       const content = scene.contents[contentId];
77:       if (!content) throw new Error(`Missing grid content: ${contentId}`);
78:       size = measureContent(content.content.ascii);
79:     }
80:     const children = box.kind === "container" && !box.collapsed
81:       ? box.children.map((child) => visit(child, origin)) : [];
82:     for (const child of children) {
83:       size.columns = Math.max(size.columns, child.bounds.column - origin.column + child.bounds.columns);
84:       size.rows = Math.max(size.rows, child.bounds.row - origin.row + child.bounds.rows);
85:     }
86:     // Reserved expanded space does not keep a collapsed box large.
87:     if (!box.collapsed && box.minimumSize) {
88:       size.columns = Math.max(size.columns, box.minimumSize.columns);
89:       size.rows = Math.max(size.rows, box.minimumSize.rows);
90:     }
91:     integer(origin.column + size.columns, "right edge");
92:     integer(origin.row + size.rows, "bottom edge");
93:     return { box, bounds: { ...origin, ...size }, contentId, children };
94:   }
95:   return visit(scene.root, { column: 0, row: 0 });
96: }
