109: /** Immutable tree edit; use layoutScene afterward to commit the resulting positions. */
110: export function updateGridBox(scene: LineGridScene, id: string, update: (box: GridBox) => GridBox): LineGridScene {
111:   let found = false;
112:   function visit(box: GridBox): GridBox {
113:     if (box.id === id) { found = true; return update(box); }
114:     return box.kind === "container" ? { ...box, children: box.children.map(visit) } : box;
115:   }
116:   const root = visit(scene.root);
