121: /**
122:  * Anchor the changed subtree at every ancestor. Settle other siblings in stable
123:  * spatial order, only moving right. Each settled box is an immutable obstacle,
124:  * so collision chains terminate without boxes repeatedly pushing each other.
125:  */
126: export function layoutScene(scene: LineGridScene, changedId: string): LineGridScene {
127:   function visit(box: GridBox): { box: GridBox; changed: boolean } {
128:     if (box.kind === "diagram") return { box, changed: box.id === changedId };
129:     const descendants = box.children.map(visit);
130:     let children = descendants.map((child) => child.box);
131:     const anchoredId = descendants.find((child) => child.changed)?.box.id;
132:     if (!box.collapsed) {
133:       const measure = (child: GridBox) => resolveScene({ ...scene, root: child }).bounds;
134:       const ordered = children.map((child, index) => ({ child, index })).sort((a, b) =>
135:         Number(b.child.id === anchoredId) - Number(a.child.id === anchoredId)
136:         || a.child.position.column - b.child.position.column
137:         || a.child.position.row - b.child.position.row || a.index - b.index);
138:       const settled: GridBounds[] = [];
139:       const replacements = new Map<string, GridBox>();
140:       for (const { child } of ordered) {
141:         const bounds = { ...measure(child) };
142:         let collisions = settled.filter((other) => boxesOverlap(bounds, other, box.layout.gap));
143:         while (collisions.length) {
144:           bounds.column = Math.max(...collisions.map((other) => other.column + other.columns + box.layout.gap));
145:           collisions = settled.filter((other) => boxesOverlap(bounds, other, box.layout.gap));
146:         }
147:         settled.push(bounds);
148:         replacements.set(child.id, { ...child, position: { column: bounds.column, row: bounds.row } });
149:       }
150:       children = children.map((child) => replacements.get(child.id)!);
151:     }
152:     return { box: { ...box, children }, changed: box.id === changedId || descendants.some((child) => child.changed) };
153:   }
154:   const result = visit(scene.root);
155:   if (!result.changed) throw new Error(`Unknown GridBox: ${changedId}`);
156:   const next = { ...scene, root: result.box };
157:   // Check all final bounds before publishing a transaction.
158:   composeScene(next);
159:   return next;
160: }
