162: export function composeScene(scene: LineGridScene, renderContent?: (content: Diagram, box: GridBox) => string): string {
163:   const root = resolveScene(scene);
164:   const width = root.bounds.column + root.bounds.columns;
165:   const height = root.bounds.row + root.bounds.rows;
166:   if (width * height > MAX_CELLS) throw new Error("Grid exceeds the supported canvas size");
167:   const rows = Array.from({ length: height }, () => "");
168:   function paint(node: ResolvedGridBox): void {
169:     for (let i = 0; i < node.children.length; i++) {
170:       for (let j = i + 1; j < node.children.length; j++) {
171:         if (boxesOverlap(node.children[i].bounds, node.children[j].bounds)) {
172:           throw new Error(`GridBox collision: ${node.children[i].box.id} and ${node.children[j].box.id}`);
173:         }
174:       }
175:     }
176:     if (node.contentId) {
177:       const content = scene.contents[node.contentId];
178:       (renderContent ? renderContent(content, node.box) : content.content.ascii).split("\n").forEach((line, index) => {
179:         const row = node.bounds.row + index;
180:         const start = node.bounds.column;
181:         const existing = rows[row].padEnd(start, " ");
182:         rows[row] = existing.slice(0, start) + line + existing.slice(start + line.length);
183:       });
184:     }
185:     node.children.forEach(paint);
186:   }
187:   paint(root);
188:   return rows.join("\n");
189: }
