191: export function hitTest(scene: LineGridScene, point: GridPoint): { boxId: string; contentId?: string; local: GridPoint } | null {
192:   function visit(node: ResolvedGridBox): ReturnType<typeof hitTest> {
193:     const b = node.bounds;
194:     if (point.column < b.column || point.column >= b.column + b.columns
195:       || point.row < b.row || point.row >= b.row + b.rows) return null;
196:     for (const child of node.children) {
197:       const hit = visit(child);
198:       if (hit) return hit;
199:     }
200:     return { boxId: node.box.id, contentId: node.contentId,
201:       local: { column: point.column - b.column, row: point.row - b.row } };
202:   }
203:   return visit(resolveScene(scene));
204: }
