619: function findOwner(root: LineGridScene['root'], displayNodeId: string): LineGridScene['root'] | undefined {
620:   if (`grid:${root.id}` === displayNodeId) return root;
621:   return root.kind === 'container' ? root.children.map(child => findOwner(child, displayNodeId)).find(Boolean) : undefined;
622: }
623: function encodeAnchor(anchor: DiagramAnchor, key: string, scene: LineGridScene, bindings: Record<string, string>,
624:   revisions: Record<string, DiagramRevision>, unresolved: Record<string, ContentNodeAnchor>): CanvasConnection['target'] {
625:   if (anchor.kind === 'box') return structuredClone(anchor);
626:   const box = findOwner(scene.root, anchor.displayNodeId);
627:   const revision = box?.kind === 'diagram' && revisions[bindings[box.contentId]];
628:   const ref = revision && revision.diagram.content.revisionId === anchor.revisionId && revision.nodeRefs[anchor.contentNodeId];
629:   const { revisionId: _, ...rest } = anchor;
630:   if (!ref) unresolved[key] = structuredClone(anchor);
631:   return { ...rest, contentNodeId: ref || `unresolved:${anchor.contentNodeId}` };
632: }

